function rampartSimulate(createStrategy, seed, maxTicks, rec) {
  var TT = ["bolt", "cannon", "frost", "lance", "flak"];
  var TD = {
    bolt:   { cost: 50,  dmg: 26,  per: 8,  rng: 300, spl: 0,  slow: 0,  pierce: 0, g: 1, a: 1 },
    cannon: { cost: 90,  dmg: 60,  per: 24, rng: 260, spl: 90, slow: 0,  pierce: 0, g: 1, a: 0 },
    frost:  { cost: 70,  dmg: 10,  per: 12, rng: 240, spl: 0,  slow: 30, pierce: 0, g: 1, a: 1 },
    lance:  { cost: 120, dmg: 180, per: 36, rng: 360, spl: 0,  slow: 0,  pierce: 1, g: 1, a: 0 },
    flak:   { cost: 80,  dmg: 40,  per: 10, rng: 320, spl: 70, slow: 0,  pierce: 0, g: 0, a: 1 }
  };
  var ET = {
    grunt:     { hp: 60,  sp: 10, bty: 4, leak: 1, air: 0, first: 1, w: 10 },
    runner:    { hp: 40,  sp: 20, bty: 4, leak: 1, air: 0, first: 2, w: 4 },
    wisp:      { hp: 50,  sp: 12, bty: 6, leak: 2, air: 1, first: 3, w: 3 },
    brute:     { hp: 150, sp: 6,  bty: 9, leak: 3, air: 0, first: 4, w: 3 },
    splitter:  { hp: 90,  sp: 8,  bty: 6, leak: 2, air: 0, first: 6, w: 2 },
    mender:    { hp: 70,  sp: 8,  bty: 7, leak: 2, air: 0, first: 8, w: 1 },
    splitling: { hp: 0,   sp: 12, bty: 1, leak: 1, air: 0, first: 9999, w: 0 }
  };
  var ORDER = ["grunt", "runner", "wisp", "brute", "splitter", "mender"];
  var SLOTS = [[3,3],[5,5],[7,4],[7,8],[9,9],[10,5],[11,8],[13,8],[14,5],[15,2],[16,7],[17,4],[19,8],[20,10],[22,9],[3,7]];
  function mkRoute(pts) {
    var p = [], cum = [0];
    for (var i = 0; i < pts.length; i++) p.push([pts[i][0] * 100 + 50, pts[i][1] * 100 + 50]);
    for (var j = 1; j < p.length; j++) cum.push(cum[j - 1] + Math.abs(p[j][0] - p[j - 1][0]) + Math.abs(p[j][1] - p[j - 1][1]));
    return { p: p, cum: cum, len: cum[cum.length - 1] };
  }
  var GROUND = mkRoute([[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]]);
  var AIR = mkRoute([[0,6],[21,6],[21,11],[23,11]]);
  function posAt(r, d) {
    var n = r.p.length;
    if (d <= 0) return [r.p[0][0], r.p[0][1]];
    for (var i = 1; i < n; i++) {
      if (d <= r.cum[i]) {
        var a = r.p[i - 1], b = r.p[i], t = d - r.cum[i - 1];
        return [a[0] + Math.sign(b[0] - a[0]) * t, a[1] + Math.sign(b[1] - a[1]) * t];
      }
    }
    return [r.p[n - 1][0], r.p[n - 1][1]];
  }
  function mulberry32(a) { return function () {
    a = (a + 0x6D2B79F5) | 0; var t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return (t ^ (t >>> 14)) >>> 0; }; }
  var rng = mulberry32(seed);
  var mCache = [0, 1000];
  function mult(w) { while (mCache.length <= w) mCache.push(Math.floor(mCache[mCache.length - 1] * 108 / 100)); return mCache[w]; }
  function armorOf(type, w) { return type === "grunt" ? Math.floor(w / 4) : type === "brute" ? 6 + w : 0; }
  function genWave(w) {
    var n = 4 + Math.floor(3 * w / 5), list = [], tw = 0, avail = [];
    for (var k = 0; k < ORDER.length; k++) if (ET[ORDER[k]].first <= w) { avail.push(ORDER[k]); tw += ET[ORDER[k]].w; }
    for (var i = 0; i < n; i++) {
      var r = rng() % tw;
      for (var j = 0; j < avail.length; j++) { var wt = ET[avail[j]].w; if (r < wt) { list.push(avail[j]); break; } r -= wt; }
    }
    return list;
  }
  function tdmg(type, tier) { var d = TD[type].dmg; for (var i = 1; i < tier; i++) d = Math.floor(d * 16 / 10); return d; }
  function trng(type, tier) { return TD[type].rng + 30 * (tier - 1); }

  var log = [], gold = 250, baseHp = 10, wave = 0, nextId = 1, fallTick = -1, endTick = maxTicks;
  var turrets = []; for (var s = 0; s < 16; s++) turrets.push(null);
  var enemies = [], queue = [];
  var waves = [null, genWave(1)];
  var strat = createStrategy();

  function view(e) {
    return { id: e.id, type: e.type, hp: e.hp, maxHp: e.maxHp, x: e.x, y: e.y, air: e.air, armor: e.armor,
      speed: e.sp, slowed: e.slow > 0 ? 1 : 0, remaining: e.route.len - e.progress };
  }
  function makeEnemy(type, w, progress, maxHp) {
    var d = ET[type], r = d.air ? AIR : GROUND;
    var e = { id: nextId++, type: type, wave: w, maxHp: maxHp, hp: maxHp, sp: d.sp, armor: armorOf(type, w), air: d.air,
      route: r, progress: progress, age: 0, slow: 0, x: 0, y: 0, alive: true };
    var p = posAt(r, progress); e.x = p[0]; e.y = p[1];
    return e;
  }
  function stateCopy(tick) {
    var sl = [];
    for (var i = 0; i < 16; i++) {
      var t = turrets[i];
      sl.push({ slot: i, x: SLOTS[i][0] * 100 + 50, y: SLOTS[i][1] * 100 + 50, turret: t ? { type: t.type, tier: t.tier, spent: t.spent } : null });
    }
    var ev = []; for (var j = 0; j < enemies.length; j++) ev.push(view(enemies[j]));
    return { tick: tick, wave: wave, gold: gold, baseHp: baseHp, slots: sl, enemies: ev, nextWave: waves[wave + 1].slice() };
  }
  function applyActions(acts, tick) {
    if (!Array.isArray(acts)) return;
    var n = Math.min(32, acts.length);
    for (var i = 0; i < n; i++) {
      var a = acts[i];
      if (!a || typeof a !== "object") continue;
      var sl = a.slot;
      if (typeof sl !== "number" || !(sl >= 0 && sl < 16) || Math.floor(sl) !== sl) continue;
      var t = turrets[sl];
      if (a.op === "build") {
        if (t || typeof a.type !== "string" || !TD.hasOwnProperty(a.type)) continue;
        var c = TD[a.type].cost; if (gold < c) continue;
        gold -= c;
        turrets[sl] = { slot: sl, type: a.type, tier: 1, spent: c, cd: 0, x: SLOTS[sl][0] * 100 + 50, y: SLOTS[sl][1] * 100 + 50 };
        log.push([tick, "B", sl, TT.indexOf(a.type)]);
      } else if (a.op === "upgrade") {
        if (!t || t.tier >= 3) continue;
        var uc = TD[t.type].cost * (t.tier === 1 ? 1 : 2); if (gold < uc) continue;
        gold -= uc; t.spent += uc; t.tier++;
        log.push([tick, "U", sl, t.tier]);
      } else if (a.op === "sell") {
        if (!t) continue;
        gold += Math.floor(t.spent * 70 / 100); turrets[sl] = null;
        log.push([tick, "S", sl, 0]);
      }
    }
  }

  var shots = null, kills = null, heals = null, leaks = null;
  for (var tick = 0; tick < maxTicks; tick++) {
    if (rec) { shots = []; kills = []; heals = []; leaks = []; }
    var fell = false;
    // 1. wave start
    if (tick >= 20 && (tick - 20) % 40 === 0) {
      wave = (tick - 20) / 40 + 1;
      gold += Math.min(50, Math.floor(gold * 5 / 100)) + 10 + 2 * wave;
      waves[wave + 1] = genWave(wave + 1);
      var acts = strat.plan(stateCopy(tick));
      applyActions(acts, tick);
      var wl = waves[wave];
      for (var qi = 0; qi < wl.length; qi++) queue.push({ t: tick + 4 * qi, w: wave, i: qi, type: wl[qi] });
      queue.sort(function (a, b) { return a.t - b.t || a.w - b.w || a.i - b.i; });
      waves[wave - 1] = null;
    }
    // 2. spawn
    while (queue.length && queue[0].t === tick) {
      var q = queue.shift();
      enemies.push(makeEnemy(q.type, q.w, 0, Math.floor(ET[q.type].hp * mult(q.w) / 1000)));
    }
    // 3. move
    for (var ei = 0; ei < enemies.length; ei++) {
      var e = enemies[ei];
      var spd = e.slow > 0 ? Math.floor(e.sp * 60 / 100) : e.sp;
      e.progress += spd;
      if (e.progress >= e.route.len) {
        e.progress = e.route.len;
        baseHp -= ET[e.type].leak;
        log.push([tick, "L", e.id, baseHp]);
        if (rec) leaks.push([e.id, ET[e.type].leak]);
        e.alive = false;
        enemies.splice(ei, 1); ei--;
        if (baseHp <= 0) { fell = true; break; }
      } else {
        var pp = posAt(e.route, e.progress); e.x = pp[0]; e.y = pp[1];
      }
    }
    if (fell) {
      log.push([tick, "F", wave, 0]);
      fallTick = tick; endTick = tick;
      if (rec) rec(tick, { enemies: enemies, turrets: turrets, gold: gold, baseHp: baseHp, wave: wave, shots: shots, kills: kills, heals: heals, leaks: leaks, fell: true, nextWave: waves[wave + 1] });
      break;
    }
    // 4. age & heal
    for (var ai = 0; ai < enemies.length; ai++) {
      var m = enemies[ai]; m.age++;
      if (m.type === "mender" && m.age % 20 === 0) {
        if (rec) heals.push([m.x, m.y]);
        for (var hj = 0; hj < enemies.length; hj++) {
          var h = enemies[hj], hx = h.x - m.x, hy = h.y - m.y;
          if (hx * hx + hy * hy <= 22500) h.hp = Math.min(h.maxHp, h.hp + Math.floor(h.maxHp * 8 / 100));
        }
      }
    }
    // 5. turrets fire
    for (var si = 0; si < 16; si++) {
      var T = turrets[si]; if (!T) continue;
      if (T.cd > 0) { T.cd--; if (T.cd > 0) continue; }
      var D = TD[T.type], R = trng(T.type, T.tier), R2 = R * R, cands = [];
      for (var ci = 0; ci < enemies.length; ci++) {
        var c2 = enemies[ci];
        if (c2.air ? !D.a : !D.g) continue;
        var dx = c2.x - T.x, dy = c2.y - T.y;
        if (dx * dx + dy * dy <= R2) cands.push(c2);
      }
      if (!cands.length) continue;
      var tgt = null;
      if (typeof strat.target === "function") {
        var cv = []; for (var vi = 0; vi < cands.length; vi++) cv.push(view(cands[vi]));
        var pick = strat.target({ slot: si, type: T.type, tier: T.tier, x: T.x, y: T.y, range: R }, cv);
        for (var pi = 0; pi < cands.length; pi++) if (cands[pi].id === pick) { tgt = cands[pi]; break; }
      }
      if (!tgt) {
        tgt = cands[0];
        for (var di = 1; di < cands.length; di++) {
          var rr = cands[di].route.len - cands[di].progress, rb = tgt.route.len - tgt.progress;
          if (rr < rb) tgt = cands[di];
        }
      }
      var dmg = tdmg(T.type, T.tier);
      var hitList;
      if (D.spl > 0) {
        hitList = []; var S2 = D.spl * D.spl;
        for (var hi = 0; hi < enemies.length; hi++) {
          var o = enemies[hi];
          if (o.hp <= 0) continue;
          if (o.air ? !D.a : !D.g) continue;
          var ox = o.x - tgt.x, oy = o.y - tgt.y;
          if (ox * ox + oy * oy <= S2) hitList.push(o);
        }
      } else hitList = [tgt];
      for (var hk = 0; hk < hitList.length; hk++) {
        var v = hitList[hk];
        v.hp -= D.pierce ? dmg : Math.max(1, dmg - v.armor);
        if (D.slow > 0) v.slow = D.slow;
      }
      T.cd = D.per;
      if (rec) shots.push([si, T.type, tgt.id, tgt.x, tgt.y, T.tier]);
      var survivors = [], spawned = [];
      for (var ki = 0; ki < enemies.length; ki++) {
        var k = enemies[ki];
        if (k.hp <= 0) {
          k.alive = false;
          gold += ET[k.type].bty;
          log.push([tick, "K", k.id, si]);
          if (rec) kills.push([k.id, k.type, k.x, k.y, si]);
          if (k.type === "splitter") {
            var shp = Math.max(1, Math.floor(k.maxHp / 4));
            for (var sp3 = 0; sp3 < 3; sp3++) {
              var ns = makeEnemy("splitling", k.wave, k.progress, shp);
              ns.parent = k.id; spawned.push(ns);
            }
          }
        } else survivors.push(k);
      }
      enemies = survivors.concat(spawned);
    }
    // 6. slow timers
    for (var sj = 0; sj < enemies.length; sj++) if (enemies[sj].slow > 0) enemies[sj].slow--;
    if (rec) rec(tick, { enemies: enemies, turrets: turrets, gold: gold, baseHp: baseHp, wave: wave, shots: shots, kills: kills, heals: heals, leaks: leaks, fell: false, nextWave: waves[wave + 1] });
  }
  var s = JSON.stringify(log), hsh = 0x811c9dc5;
  for (var hc = 0; hc < s.length; hc++) { hsh ^= s.charCodeAt(hc); hsh = Math.imul(hsh, 0x01000193); }
  return { score: Math.round((endTick - 20) / 40 * 100) / 100, fallTick: fallTick, log: log, hash: (hsh >>> 0).toString(16).padStart(8, "0") };
}
if (typeof module !== "undefined") module.exports = rampartSimulate;
