          log.push([tick, "K", k.id, si]);
          if (rec) kills.push([k.id, k.type, k.x, k.y, si, k.air]);
          if (k.type === "splitter") {
            var shp = Math.max(1, Math.floor(k.maxHp / 4));
            for (var s3 = 0; s3 < 3; s3++) spawned.push(makeEnemy("splitling", k.wave, k.progress, shp));
          }
        } else survivors.push(k);
      }
      enemies = spawned.length ? survivors.concat(spawned) : survivors;
    }
    // 6. slow timers
    for (var sj = 0; sj < enemies.length; sj++) if (enemies[sj].slow > 0) enemies[sj].slow--;
    if (rec) snap(tick, false);
  }
