  for (var hc = 0; hc < str.length; hc++) { hsh = (hsh ^ str.charCodeAt(hc)) >>> 0; hsh = Math.imul(hsh, 0x01000193) >>> 0; }
  return { score: Math.round((endTick - 20) / 40 * 100) / 100, fallTick: fallTick, log: log, hash: ("0000000" + hsh.toString(16)).slice(-8) };
}

