// Parametric strategy: P = { types: [16 type strings], queue: [slot indices; first occurrence = build, next = upgrades] }
function makeCreate(P) {
  return function createStrategy() {
    var COST = { bolt: 50, cannon: 90, frost: 70, lance: 120, flak: 80 };
    var DMG = { bolt: 26, cannon: 60, frost: 10, lance: 180, flak: 40 };
    var SPL = { cannon: 90, flak: 70 };
    var types = P.types.slice(), queue = P.queue.slice();
    function dmgOf(type, tier) { var d = DMG[type]; for (var i = 1; i < tier; i++) d = Math.floor(d * 16 / 10); return d; }
    return {
      plan: function (s) {
        var gold = s.gold, acts = [], tiers = [];
        for (var i = 0; i < 16; i++) tiers.push(s.slots[i].turret ? s.slots[i].turret.tier : 0);
        // walk the queue; count occurrences to know the desired tier for each entry
        var seen = [];
        for (var k = 0; k < 16; k++) seen.push(0);
        for (var q = 0; q < queue.length && acts.length < 32; q++) {
          var sl = queue[q]; seen[sl]++;
          var want = seen[sl];
          if (tiers[sl] >= want) continue;
          var ty = s.slots[sl].turret ? s.slots[sl].turret.type : types[sl];
          var cost = tiers[sl] === 0 ? COST[ty] : COST[ty] * (tiers[sl] === 1 ? 1 : 2);
          if (gold < cost) break;
          gold -= cost;
          if (tiers[sl] === 0) acts.push({ op: "build", slot: sl, type: ty }); else acts.push({ op: "upgrade", slot: sl });
          tiers[sl]++;
        }
        return acts;
      },
      target: function (t, c) {
        var d = dmgOf(t.type, t.tier), best = null, bs = -1, i, j, e;
        if (t.type === "cannon" || t.type === "flak") {
          var R2 = SPL[t.type] * SPL[t.type];
          for (i = 0; i < c.length; i++) {
            var sc = 0;
            for (j = 0; j < c.length; j++) {
              e = c[j]; var dx = e.x - c[i].x, dy = e.y - c[i].y;
              if (dx * dx + dy * dy <= R2) sc += Math.min(e.hp, Math.max(1, d - e.armor));
            }
            sc = sc * 10000 - c[i].remaining;
            if (sc > bs) { bs = sc; best = c[i]; }
          }
        } else if (t.type === "lance") {
          for (i = 0; i < c.length; i++) {
            e = c[i]; var sl = Math.min(e.hp, d) * 10000 - e.remaining;
            if (sl > bs) { bs = sl; best = e; }
          }
        } else if (t.type === "frost") {
          for (i = 0; i < c.length; i++) {
            e = c[i]; var sf = (e.slowed ? 0 : 1) * 1e8 + e.hp * 1000 - e.remaining;
            if (sf > bs) { bs = sf; best = e; }
          }
        } else {
          for (i = 0; i < c.length; i++) {
            e = c[i]; var sb = Math.min(e.hp, Math.max(1, d - e.armor)) * 10000 - e.remaining;
            if (sb > bs) { bs = sb; best = e; }
          }
        }
        return best ? best.id : undefined;
      }
    };
  };
}

