// Parametric strategy with tunable targeting TG
function makeCreate2(P, TG) {
  return function createStrategy() {
    var COST = { bolt: 50, cannon: 90, frost: 70, lance: 120, flak: 80 };
    var DMG = { bolt: 26, cannon: 60, frost: 10, lance: 180, flak: 40 };
    var SPL = { cannon: 90, flak: 70 };
    var types = P.types.slice(), queue = P.queue.slice();
    function dmgOf(type, tier) { var d = DMG[type]; for (var i = 1; i < tier; i++) d = Math.floor(d * 16 / 10); return d; }
    function urg(e) { var sp = e.slowed ? Math.floor(e.speed * 60 / 100) : e.speed; return 1 / (e.remaining / Math.max(1, sp) + TG.K); }
    return {
      plan: function (s) {
        var gold = s.gold, acts = [], tiers = [], seen = [];
        for (var i = 0; i < 16; i++) { tiers.push(s.slots[i].turret ? s.slots[i].turret.tier : 0); seen.push(0); }
        for (var q = 0; q < queue.length && acts.length < 32; q++) {
          var sl = queue[q]; seen[sl]++;
          if (tiers[sl] >= seen[sl]) continue;
          var ty = s.slots[sl].turret ? s.slots[sl].turret.type : types[sl];
          var cost = tiers[sl] === 0 ? COST[ty] : COST[ty] * (tiers[sl] === 1 ? 1 : 2);
          if (gold < cost) break;
          gold -= cost;
          acts.push(tiers[sl] === 0 ? { op: "build", slot: sl, type: ty } : { op: "upgrade", slot: sl });
          tiers[sl]++;
        }
        return acts;
      },
      target: function (t, c) {
        var d = dmgOf(t.type, t.tier), best = null, bs = -Infinity, i, j, e, sc;
        var pierce = t.type === "lance";
        for (i = 0; i < c.length; i++) {
          if (SPL[t.type]) {
            var R2 = SPL[t.type] * SPL[t.type]; sc = 0;
            for (j = 0; j < c.length; j++) {
              e = c[j]; var dx = e.x - c[i].x, dy = e.y - c[i].y;
              if (dx * dx + dy * dy <= R2) { var ef = Math.min(e.hp, Math.max(1, d - e.armor)); sc += ef * (TG.su ? urg(e) : 1) + (ef >= e.hp ? TG.kb * e.hp : 0); }
            }
            sc = sc * 1e6 - c[i].remaining;
          } else {
            e = c[i];
            var ef2 = Math.min(e.hp, pierce ? d : Math.max(1, d - e.armor));
            if (TG.mode === 0) sc = ef2 * 1e6 - e.remaining;
            else if (TG.mode === 1) sc = ef2 * urg(e) * (ef2 >= e.hp ? TG.kill : 1) + (e.type === "mender" ? TG.mend : 0);
            else sc = urg(e) * (ef2 >= e.hp ? TG.kill : 1) + (e.type === "mender" ? TG.mend : 0);
          }
          if (sc > bs) { bs = sc; best = c[i]; }
        }
        return best ? best.id : undefined;
      }
    };
  };
}

