function createStrategy() {
  // Build/upgrade queue tuned offline by hill-climbing on 40 training seeds and checked on
  // separate validation seeds (seed 42 was never used for tuning).
  // First occurrence of a slot in QUEUE builds TYPES[slot]; later occurrences upgrade it.
  // The queue is followed strictly in order: if the next item is unaffordable we save gold.
  var TYPES = __TYPES__;
  var QUEUE = __QUEUE__;
  var COST = { bolt: 50, cannon: 90, frost: 70, lance: 120, flak: 80 };
  var DMG = { bolt: 26, cannon: 60, frost: 10, lance: 180, flak: 40 };
  var SPL = { cannon: 90, flak: 70 };
  function dmgOf(type, tier) { var d = DMG[type]; for (var i = 1; i < tier; i++) d = Math.floor(d * 16 / 10); return d; }
  // urgency: inverse of the ticks this enemy needs to reach the keep (plus a constant)
  function urg(e) { var sp = e.slowed ? Math.floor(e.speed * 60 / 100) : e.speed; return 1 / (e.remaining / Math.max(1, sp) + 50); }
  return {
    plan: function (s) {
      var gold = s.gold, acts = [], tiers = [], seen = [], i;
      for (i = 0; i < 16; i++) { tiers.push(s.slots[i].turret ? s.slots[i].turret.tier : 0); seen.push(0); }
      for (var q = 0; q < QUEUE.length && acts.length < 32; q++) {
        var sl = QUEUE[q]; seen[sl]++;
        if (tiers[sl] >= seen[sl]) continue;
        var ty = s.slots[sl].turret ? s.slots[sl].turret.type : TYPES[sl];
        var cost = tiers[sl] === 0 ? COST[ty] : COST[ty] * (tiers[sl] === 1 ? 1 : 2);
        if (gold < cost) break;
        gold -= cost;
        acts.push(tiers[sl] === 0 ? { op: "build", slot: sl, type: ty } : { op: "upgrade", slot: sl });
        tiers[sl]++;
      }
      return acts;
    },
    target: function (t, c) {
      var d = dmgOf(t.type, t.tier), best = null, bs = -Infinity, i, j, e, sc;
      for (i = 0; i < c.length; i++) {
        if (SPL[t.type]) {
          // splash: maximise urgency-weighted useful damage over everything in the blast
          var R2 = SPL[t.type] * SPL[t.type]; sc = 0;
          for (j = 0; j < c.length; j++) {
            e = c[j]; var dx = e.x - c[i].x, dy = e.y - c[i].y;
            if (dx * dx + dy * dy <= R2) sc += Math.min(e.hp, Math.max(1, d - e.armor)) * urg(e);
          }
          sc = sc * 1e6 - c[i].remaining;
        } else {
          // single target: menders first, then whoever reaches the keep soonest
          e = c[i];
          sc = urg(e) + (e.type === "mender" ? 1 : 0);
        }
        if (sc > bs) { bs = sc; best = c[i]; }
      }
      return best ? best.id : undefined;
    }
  };
}

